  cycle_nudge_menstruation_body: "Jour de règles. Ton corps commence déjà la sélection du follicule principal du prochain cycle. Repas chauds, sommeil profond — le travail se fait même quand on ne le sent pas.",
  cycle_nudge_follicular_headline: "L'énergie *monte*",
  cycle_nudge_follicular_body: "Les œstrogènes grimpent. Peau, humeur, libido — c'est la phase de construction. Belle fenêtre pour le renforcement musculaire, les projets, les sorties.",
