  cycle_nudge_ovulation_body: "Fertilité maximale. Si tu essaies, aujourd'hui et les deux prochains jours sont ta meilleure fenêtre du cycle.",
  cycle_nudge_luteal_headline: "Le SPM est *hormonal*, pas personnel",
  cycle_nudge_luteal_body: "La progestérone baisse. Des aliments riches en magnésium (chocolat noir, amandes, bananes) et une marche avant de dormir aident plus qu'on ne le croit.",
  cycle_nudge_late_headline: "Tu as *quelques jours de retard*",
  cycle_nudge_late_body: "Pas encore un verdict — mais une bonne journée pour faire un test si tu suis ton cycle.",
  cycle_nudge_follicular_lh_headline: "C'est le moment de commencer les *tests LH*",
  cycle_nudge_follicular_lh_body: "Tu es à quelques jours de ton pic prévu. Fais un test ce soir ou demain matin.",
