  cycle_nudge_from: "De",
  cycle_nudge_read_more: "Lire la suite →",
  cycle_nudge_reflect_from: "Un moment pour toi",
  cycle_nudge_log_it: "Noter →",
  cycle_nudge_menstruation_iron_headline: "Refais le plein de *fer*",
  cycle_nudge_menstruation_iron_body: "Les saignements puisent dans les réserves de fer, ma chère. Associe un plat d'épinards ou de lentilles à quelque chose d'acidulé — la vitamine C double à peu près l'absorption.",
  cycle_nudge_menstruation_warmth_headline: "Sois *douce* avec toi aujourd'hui",
  cycle_nudge_menstruation_warmth_body: "Les prostaglandines provoquent les crampes. Une bouillotte et un mouvement lent soulagent aussi bien que la plupart des antidouleurs — et ton énergie est à son plus bas en ce moment, c'est ainsi fait.",
  cycle_nudge_follicular_plan_headline: "Un bon jour pour *voir plus loin*",
  cycle_nudge_follicular_plan_body: "La hausse des œstrogènes aiguise la concentration et l'humeur. Profite de cette phase de construction pour les réflexions plus ardues, les séances plus costaudes, les conversations que tu repoussais.",
  cycle_nudge_follicular_hydrate_headline: "Observe ta *glaire cervicale*",
  cycle_nudge_follicular_hydrate_body: "Elle devrait devenir plus claire et plus filante à l'approche de la fenêtre. La glaire est surtout de l'eau — 2 à 2,5 litres par jour gardent le signal lisible.",
  cycle_nudge_ovulation_timing_headline: "Les *deux jours avant* comptent le plus",
  cycle_nudge_ovulation_timing_body: "Les spermatozoïdes vivent jusqu'à cinq jours ; l'ovule seulement 12 à 24 heures. Vise la période qui précède, pas le jour exact — la fréquence compte plus que la précision.",
  cycle_nudge_luteal_sleep_headline: "Protège ton *sommeil* cette semaine",
  cycle_nudge_luteal_sleep_body: "La progestérone fait monter la température du corps et fragmente le sommeil. Une chambre plus fraîche et un coucher plus tôt apaisent l'humeur plus que tu ne l'imagines.",
  cycle_nudge_luteal_move_headline: "Une marche vaut mieux que la *spirale*",
  cycle_nudge_luteal_move_body: "Les baisses de fin de phase lutéale sont hormonales, pas un verdict sur ta vie. Vingt minutes de lumière du jour et de mouvement remettent les choses en place mieux que le défilement d'écran.",
  cycle_nudge_fertility_follicular_headline: "Ta fenêtre *approche*",
  cycle_nudge_fertility_follicular_body: "Les œstrogènes montent vers l'ovulation. Les cinq jours avant l'ovulation forment ta fenêtre fertile — les spermatozoïdes peuvent attendre l'ovule aussi longtemps.",
  cycle_nudge_fertility_luteal_headline: "La fenêtre s'est *refermée*",
  cycle_nudge_fertility_luteal_body: "L'ovule ne vit que 12 à 24 heures, cette partie du cycle offre donc peu de chances. Si tu as fait des tests ou planifié, il ne reste qu'à patienter.",
  cycle_nudge_fertility_menstruation_headline: "Un *nouveau* cycle commence",
  cycle_nudge_fertility_menstruation_body: "Le premier jour remet le compteur à zéro. Ta prochaine fenêtre fertile est à environ deux semaines — un temps calme pour te reposer et te préparer avant son ouverture.",
  cycle_nudge_reflect_mood_headline: "Comment te *sens*-tu aujourd'hui ?",
  cycle_nudge_reflect_mood_body: "Un petit point sur ton humeur dessine peu à peu le tableau — les tendances par phase se voient mieux après quelques cycles notés.",
  cycle_nudge_reflect_symptom_headline: "Tu remarques *quelque chose* aujourd'hui ?",
  cycle_nudge_reflect_symptom_body: "Crampes, seins sensibles, mal de tête ? Noter tes symptômes t'aide, toi et ton médecin, à repérer ce qui revient chez toi.",
  cycle_nudge_reflect_energy_headline: "Où en est ton *énergie* ?",
  cycle_nudge_reflect_energy_body: "L'énergie baisse naturellement avant les règles. La noter aujourd'hui t'aide à t'organiser selon ton propre rythme plutôt que de lutter contre lui.",
  cycle_nudge_nutrition_luteal_headline: "Pense au *magnésium*",
  cycle_nudge_nutrition_luteal_body: "Chocolat noir, amandes, graines de courge et bananes apaisent les crampes et stabilisent l'humeur en seconde moitié de cycle. Associe-les à des glucides complexes pour adoucir les envies.",
  cycle_nudge_nutrition_ovulation_headline: "Nourris l'*ovule*",
  cycle_nudge_nutrition_ovulation_body: "Les aliments riches en antioxydants — baies, légumes verts, noix — soutiennent la qualité de l'ovule. Le zinc (graines de courge, pois chiches) compte surtout autour de l'ovulation.",
  cycle_nudge_edu_menstruation_headline: "Tes règles sont le *premier* jour",
  cycle_nudge_edu_menstruation_body: "Le jour 1 du cycle est le premier jour de vrais saignements, pas de simples traces. C'est le repère à partir duquel toute prédiction est comptée — bien le noter affine tout le reste.",
  cycle_nudge_edu_follicular_headline: "Un seul follicule *l'emporte*",
  cycle_nudge_edu_follicular_body: "Plusieurs follicules se mettent à grandir à chaque cycle, mais généralement un seul mûrit et libère un ovule. C'est la hausse des œstrogènes qui guide cette sélection.",
  cycle_nudge_edu_ovulation_headline: "Un événement de *36 heures*",
  cycle_nudge_edu_ovulation_body: "L'ovulation elle-même est brève — le pic de LH déclenche la libération en 24 à 36 heures environ. C'est pourquoi les bandelettes LH servent à repérer le pic, pas la libération.",
  cycle_nudge_edu_luteal_headline: "L'attente de *deux semaines*",
  cycle_nudge_edu_luteal_body: "La phase lutéale est remarquablement stable — généralement 12 à 14 jours, quelle que soit la durée du cycle. La plupart des variations viennent de la première moitié, pas de celle-ci.",
  cycle_pillar_fertility: "Bases de la fertilité",
