  cycle_conf_calendar: "Estimation basée sur le calendrier. Ajoute ta température (BBT) et les tests LH des 3 prochains jours pour affiner la prévision.",
  cycle_conf_bbt_only: "Calendrier + ta température (BBT). Ajoute des bandelettes LH pour dépasser 90 % de confiance.",
  cycle_conf_bbt_lh: "Calendrier + BBT + LH — la confiance est élevée. On attend la hausse de température après l'ovulation pour confirmer le pic.",
  cycle_conf_shift_confirmed: "Hausse de température (BBT) confirmée. Le pic passé est verrouillé. Les fenêtres à venir restent basées sur le calendrier.",
