  sw2_leap19_name: "Événements",
  sw2_leap19_desc: "Comprendre que les actions s’enchaînent",
  sw2_leap19_brain: "À cette période, les bébés commencent souvent à voir le monde comme une suite d’événements plutôt que comme un grand flou. Les actions ont un début, un milieu et une fin. C’est le début de la pensée de cause à effet, et c’est pourquoi tout peut soudain sembler fascinant.",
  sw2_leap19_tip: "Joue à des jeux simples de cause à effet, comme coucou — bébé apprend que les événements ont des résultats prévisibles.",
  sw2_leap19_ph0: "Collant, pleure quand on le pose, sommeil perturbé. Bébé peut être fatigué par tant de nouveautés en même temps.",
  sw2_leap19_ph1: "Bébé est souvent occupé à relier chaque action à ce qui se passe ensuite : pousser, lâcher, observer de près.",
  sw2_leap19_ph2: "Les gestes volontaires apparaissent, ainsi que les débuts de la permanence de l’objet : bébé cherche ce qui est tombé.",
  sw2_leap19_sg0: "Plus d’angoisse de séparation",
  sw2_leap19_sg1: "Très collant",
  sw2_leap19_sg2: "Pleure quand un jouet tombe",
  sw2_leap19_sg3: "Résiste aux siestes",
  sw2_leap19_sg4: "Réclame de l’attention",
  sw2_leap19_sg5: "Frustré quand la routine change",
  sw2_leap19_sk0: "Tend la main et attrape volontairement",
  sw2_leap19_sk1: "Secoue et tape les jouets",
  sw2_leap19_sk2: "Reconnaît les jeux",
  sw2_leap19_sk3: "Comprend « en haut » et « en bas »",
  sw2_leap19_sk4: "Suit des yeux les objets en mouvement",
  sw2_leap19_sk5: "Rit aux surprises",
  sw2_leap19_ac0: "Jeux de coucou et de cache-cache",
  sw2_leap19_ac1: "Se faire rouler une balle",
  sw2_leap19_ac2: "Jouets simples de cause à effet (appuyer = son)",
  sw2_leap19_ac3: "Raconte la routine du jour étape par étape",
  sw2_leap5_name: "Sensations nouvelles",
  sw2_leap5_desc: "Bébé découvre un monde de sensations plus riche",
  sw2_leap5_brain: "Vers cette période, ton bébé peut commencer à percevoir beaucoup plus de détails : des images plus nettes, des sons plus riches, de nouvelles sensations dans le corps. Ça peut être beaucoup, et merveilleux à la fois.",
  sw2_leap5_ph0: "Plus de pleurs, de besoin de contact et un sommeil agité sont fréquents. Bébé reçoit peut-être beaucoup de nouvelles informations sensorielles.",
  sw2_leap5_ph1: "Bébé absorbe beaucoup de nouvelles images et de nouveaux sons. L’irritabilité peut atteindre un pic avant de s’apaiser.",
  sw2_leap5_ph2: "La nouvelle conscience sensorielle s’épanouit : tu remarqueras des moments d’éveil plus longs et un regard plus attentif.",
  sw2_leap5_sg0: "Pleure plus que d’habitude",
  sw2_leap5_sg1: "Veut téter tout le temps",
  sw2_leap5_sg2: "Plus difficile à apaiser",
  sw2_leap5_sg3: "Préfère la proximité",
  sw2_leap5_sg4: "Sursaute plus facilement",
  sw2_leap5_sg5: "N’aime pas être déshabillé",
  sw2_leap5_sk0: "Réagit à la lumière et aux sons",
  sw2_leap5_sk1: "Suit du regard plus fluidement",
  sw2_leap5_sk2: "Premiers sourires sociaux",
  sw2_leap5_sk3: "Plus de moments d’éveil",
  sw2_leap5_sk4: "Se tourne vers ta voix",
  sw2_leap5_sk5: "Remarque les motifs très contrastés",
  sw2_leap5_ac0: "Tiens bébé tourné vers l’extérieur pour qu’il explore la pièce",
  sw2_leap5_ac1: "Montre-lui des cartes noir et blanc très contrastées",
  sw2_leap5_ac2: "Raconte à voix haute tout ce que tu fais",
  sw2_leap5_ac3: "Doux massage de bébé pendant les moments calmes",
  sw2_leap5_tip: "Le contact peau à peau est précieux en ce moment. Le portage et un doux bercement peuvent apaiser les jours difficiles.",
