  sw2_kh_sqGreatTag: "Proche de l’objectif",
  sw2_kh_sqGreatBlurb: "La plupart des jours, le sommeil est proche de l’objectif ou le dépasse. Un rythme régulier comme celui-ci est magnifique, continue ainsi.",
  sw2_kh_sqSolidTag: "Souvent dans l’objectif",
  sw2_kh_sqSolidBlurb: "Le sommeil est plutôt régulier ces derniers temps. Quelques nuits plus courtes font aussi partie du tableau.",
  sw2_kh_sqRestlessTag: "Un peu haché",
  sw2_kh_sqRestlessBlurb: "Quelques nuits ont été courtes. Tu peux essayer d’avancer le coucher de 15 minutes pendant quelques jours pour voir ce que ça donne.",
  sw2_kh_sqPoorTag: "Sous l’objectif ces derniers temps",
  sw2_kh_sqPoorBlurb: "Beaucoup de nuits ont été courtes ou fragmentées. Si cela dure depuis une semaine et que tu te poses des questions, en parler au pédiatre peut aider : une maladie, les dents ou un changement d’horaires peuvent jouer.",
  sw2_kh_sqNoneTag: "Ajoute un enregistrement",
  sw2_kh_sqNoneBlurb: "Aucun sommeil enregistré pour cette période. Même un seul enregistrement aide les anneaux à se remplir.",
  sw2_kh_catNote0: "En tête du menu, mon grand.",
  sw2_kh_catNote1: "Un poids lourd dans l’assiette.",
  sw2_kh_catNote2: "Joue bien son rôle.",
  sw2_kh_catNote3: "Tient bon dans l’ensemble.",
