  sw2_kh_fnLeadRight: "Le côté droit prend les devants : essaie de commencer par le gauche la prochaine fois pour équilibrer.",
  sw2_kh_fnBalanced: "Bien équilibré entre les deux côtés.",
  sw2_kh_fnShort: "Les tétées sont plutôt courtes : bébé voudra peut-être continuer s’il a encore faim.",
  sw2_kh_fnLong: "Des tétées longues et sans hâte : bébé prend son temps.",
